    v55 = { header: "\u0415\u043A\u0441\u043F\u043E\u0440\u0442\u0443\u0432\u0430\u0442\u0438 \u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u043D\u044F", label: { withBackground: "\u0422\u043B\u043E", onlySelected: "\u0422\u0456\u043B\u044C\u043A\u0438 \u0432\u0438\u0431\u0440\u0430\u043D\u0435", darkMode: "\u0422\u0435\u043C\u043D\u0438\u0439 \u0440\u0435\u0436\u0438\u043C", embedScene: "\u0412\u0431\u0443\u0434\u043E\u0432\u0430\u043D\u0430 \u0441\u0446\u0435\u043D\u0430", scale: "\u041C\u0430\u0441\u0448\u0442\u0430\u0431\u0443\u0432\u0430\u043D\u043D\u044F", padding: "\u0412\u0456\u0434\u0441\u0442\u0443\u043F" }, tooltip: { embedScene: "\u0414\u0430\u043D\u0456 \u0441\u0446\u0435\u043D\u0438 \u0431\u0443\u0434\u0443\u0442\u044C \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043D\u0456 \u0432 \u0435\u043A\u0441\u043F\u043E\u0440\u0442\u043E\u0432\u0430\u043D\u0438\u0439 \u0444\u0430\u0439\u043B PNG/SVG. \u0426\u044F \u0441\u0446\u0435\u043D\u0430 \u043C\u043E\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0456\u0434\u043D\u043E\u0432\u043B\u0435\u043D\u0430 \u0437 \u043D\u044C\u043E\u0433\u043E, \u043E\u0434\u043D\u0430\u043A \u0446\u0435 \u0437\u0431\u0456\u043B\u044C\u0448\u0438\u0442\u044C \u0440\u043E\u0437\u043C\u0456\u0440 \u0435\u043A\u0441\u043F\u043E\u0440\u0442\u043E\u0432\u0430\u043D\u043E\u0433\u043E \u0444\u0430\u0439\u043B\u0443." }, title: { exportToPng: "\u0415\u043A\u0441\u043F\u043E\u0440\u0442\u0443\u0432\u0430\u0442\u0438 \u0432 PNG", exportToSvg: "\u0415\u043A\u0441\u043F\u043E\u0440\u0442\u0443\u0432\u0430\u0442\u0438 \u0443 SVG", copyPngToClipboard: "\u0421\u043A\u043E\u043F\u0456\u044E\u0432\u0430\u0442\u0438 PNG \u0432 \u0431\u0443\u0444\u0435\u0440 \u043E\u0431\u043C\u0456\u043D\u0443" }, button: { exportToPng: "PNG", exportToSvg: "SVG", copyPngToClipboard: "\u041A\u043E\u043F\u0456\u044E\u0432\u0430\u0442\u0438 \u0432 \u0431\u0443\u0444\u0435\u0440 \u043E\u0431\u043C\u0456\u043D\u0443" } };
    x55 = { tooltip: "\u0412\u0430\u0448\u0456 \u043A\u0440\u0435\u0441\u043B\u0435\u043D\u043D\u044F \u0437\u0430\u0445\u0438\u0449\u0435\u043D\u0456 \u043D\u0430\u0441\u043A\u0440\u0456\u0437\u043D\u0438\u043C \u0448\u0438\u0444\u0440\u0443\u0432\u0430\u043D\u043D\u044F\u043C \u2014 \u0441\u0435\u0440\u0432\u0435\u0440\u0438 Excalidraw \u043D\u0456\u043A\u043E\u043B\u0438 \u0457\u0445 \u043D\u0435 \u043F\u043E\u0431\u0430\u0447\u0430\u0442\u044C.", link: "\u0414\u043E\u043F\u0438\u0441 \u0443 \u0431\u043B\u043E\u0437\u0456 \u043D\u0430 \u043D\u0430\u0441\u043A\u0440\u0456\u0437\u043D\u043E\u043C\u0443 \u0448\u0438\u0444\u0440\u0443\u0432\u0430\u043D\u043D\u0456 \u0432 Excalidraw" };
